{"content":""""Single-act demo runtime (d8-pins 4). A replica of one act's D6 E2E world."""

import json
import os
import threading
from datetime import datetime, timedelta
from pathlib import Path
from threading import Event
from typing import Any

ROOT = Path(__file__).resolve().parents[2]


def _service_for_incident(incident_id: str) -> str:
    for service in ("alert-ingestion", "intel-sync"):
        if incident_id.startswith(f"inc-{service}-"):
            return service
    return "alert-ingestion"


def _load_responses(paths: list[str]) -> list[dict[str, Any]]:
    responses: list[dict[str, Any]] = []
    for rel in paths:
        candidate = Path(rel)
        if not candidate.is_file():
            candidate = ROOT / rel
        payload = json.loads(candidate.read_text(encoding="utf-8"))
        responses.extend(payload["responses"])
    return responses


def _scripted_config() -> Any:
    from fleetsre.sre.gateway import GatewayConfig, RoleConfig

    model = "demo-scripted"
    return GatewayConfig(
        roles={"investigate": RoleConfig(
            model=model, reasoning_effort="medium"
        )},
        base_url="https://api.meta.ai/v1",
        max_retries=5,
        prices={model: {
            "input": 1.0, "cached_input": 0.5, "output": 2.0,
        }},
    )


def _live_config() -> Any:
    from fleetsre.sre.gateway import GatewayConfig, RoleConfig

    model = os.environ.get(
        "FLEETSRE_INVESTIGATE_MODEL", "muse-spark-1.3"
    )
    prices: dict[str, dict[str, float]] = {
        model: {"input": 0.0, "cached_input": 0.0, "output": 0.0}
    }
    raw = os.environ.get("FLEETSRE_PRICES_JSON", "")
    if raw:
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            data = None
        if isinstance(data, dict):
            if model in data and isinstance(data[model], dict):
                prices = {model: dict(data[model])}
            elif "input" in data and "output" in data:
                prices = {model: dict(data)}
    return GatewayConfig(
        roles={"investigate": RoleConfig(
            model=model, reasoning_effort="medium"
        )},
        base_url="https://api.meta.ai/v1",
        max_retries=5,
        prices=prices,
    )


class _CountingTransport:
    """Counts model calls and stamps each with the sim time (d8-pins 4)."""

    def __init__(self, inner: Any, clock: Any, lock: threading.RLock) -> None:
        self._inner = inner
        self._clock = clock
        self._lock = lock
        self.call_times: list[datetime] = []
        self.requests: list[dict[str, Any]] = []

    def create(
        self, request: dict[str, Any], *, timeout: float = 120.0
    ) -> dict[str, Any]:
        with self._lock:
            self.call_times.append(self._clock.now())
            self.requests.append(json.loads(json.dumps(
                request, default=str
            )))
        return self._inner.create(request, timeout=timeout)


class DemoRuntime:
    """A replica of one act's D6 end-to-end world (d8-pins 4).

    Members: act, clock, world, sink, evaluator, registry, manager,
    store, loop, transport (DemoTransport, or None when live), lock,
    started_at, held, model_calls, last_model_call_at.
    """

    def __init__(
        self,
        act: Any,
        *,
        live: bool = False,
        speed: float = 10.0,
        lead_s: int = 60,
    ) -> None:
        from fastapi.testclient import TestClient

        from fleetsre.adapters.chronicle_http import ChronicleHttpClient
        from fleetsre.clock import SimClock
        from fleetsre.contracts import load_contract
        from fleetsre.control.approvals import ApprovalStore
        from fleetsre.control.executor import Executor
        from fleetsre.control.incidents import IncidentManager
        from fleetsre.control.journal import Journal
        from fleetsre.control.loop import ControlLoop
        from fleetsre.control.verify import Verifier
        from fleetsre.demo.transport import DemoTransport
        from fleetsre.evaluator.canary import CanaryScheduler
        from fleetsre.evaluator.engine import Evaluator
        from fleetsre.mock.chronicle_api import create_app
        from fleetsre.mock.fleet import load_fleet
        from fleetsre.mock.world import World
        from fleetsre.ports import (
            MemoryLogQuery,
            MemorySink,
            MemoryStateStore,
        )
        from fleetsre.registry import Registry, deployments_from_fleet
        from fleetsre.sre.gateway import ModelGateway, OpenAITransport
        from fleetsre.sre.investigator import Investigator
        from fleetsre.sre.session import MemorySessionStore
        from fleetsre.sre.tools import ToolSet

        self.act = act
        self.live = live
        self.speed = speed
        self.lead_s = lead_s
        self.act_name = ""
        self.lock: threading.RLock = threading.RLock()
        t0: datetime = act.t0

        service = _service_for_incident(act.incident)
        fleet = load_fleet(ROOT / "fixtures" / "fleet.yaml")
        contract = load_contract(ROOT / "contracts" / f"{service}.json")
        clock = SimClock(t0)
        sink = MemorySink()
        world = World(fleet, act.seed, clock, sink)
        world.schedule([fault.schedule_item() for fault in act.faults])
        deployments = deployments_from_fleet(fleet, contract)
        evaluator = Evaluator([contract], deployments, clock)
        scheduler = CanaryScheduler(world, evaluator, [contract], clock)

        if live:
            inner: Any = OpenAITransport(
                api_key=os.environ.get("MODEL_API_KEY", ""),
                base_url="https://api.meta.ai/v1",
            )
            config = _live_config()
            transport: Any = None
            script_length = 0
        else:
            responses = _load_responses(list(act.responses))
            transport = DemoTransport(responses)
            inner = transport
            config = _scripted_config()
            script_length = len(responses)
        counting = _CountingTransport(inner, clock, self.lock)
        gateway = ModelGateway(config, counting)

        log_query = MemoryLogQuery(sink)
        http: Any = TestClient(create_app(world, dev_auth=True))
        obs: Any = ChronicleHttpClient(http, "obs-reader")
        deployer: Any = ChronicleHttpClient(http, "deployer")
        reader: Any = ChronicleHttpClient(http, "obs-reader")
        state = MemoryStateStore()
        registry = Registry([contract], deployments)
        tools = ToolSet(
            log_query, obs, state, registry, clock=clock,
            verification=True,
        )
        store = MemorySessionStore()
        investigator = Investigator(tools, gateway, store)
        approvals = ApprovalStore(clock)
        journal = Journal()
        executor = Executor(deployer, approvals, journal, clock=clock)
        verifier = Verifier(evaluator, registry, clock)
        manager = IncidentManager(
            evaluator, investigator, approvals, executor, verifier,
            state, clock, registry=registry, reader=reader,
        )
        loop = ControlLoop(
            world, evaluator, scheduler, manager, sink, t0=t0,
            tick_seconds=act.tick_seconds,
        )

        self.clock = clock
        self.world = world
        self.sink = sink
        self.evaluator = evaluator
        self.registry = registry
        self.manager = manager
        self.store = store
        self.loop = loop
        self.transport = transport
        self.gateway = gateway
        self._counting = counting
        self.script_length = script_length
        self.started_at: datetime = t0

    @property
    def model_calls(self) -> int:
        with self.lock:
            return len(self._counting.call_times)

    @property
    def last_model_call_at(self) -> datetime | None:
        with self.lock:
            if not self._counting.call_times:
                return None
            return self._counting.call_times[-1]

    @property
    def call_times(self) -> list[datetime]:
        with self.lock:
            return list(self._counting.call_times)

    @property
    def held(self) -> bool:
        with self.lock:
            return self._is_held()

    def _is_held(self) -> bool:
        from fleetsre.control.incidents import IncidentState

        for record in self.manager.incidents():
            if record.id == self.act.incident:
                return record.state == IncidentState.AWAITING_APPROVAL
        return False

    def start(self) -> None:
        """Step until first_fault_at - lead_s; record started_at."""
        with self.lock:
            first_at = self.act.t0 + timedelta(
                seconds=min(fault.at for fault in self.act.faults)
            )
            target = first_at - timedelta(seconds=self.lead_s)
            while self.clock.now() < target:
                self.loop.step()
            self.started_at = self.clock.now()

    def advance(self, seconds: float) -> None:
        """Step until the clock has moved `seconds` (d8-pins 4, 9)."""
        with self.lock:
            target = self.clock.now() + timedelta(seconds=seconds)
            while self.clock.now() < target:
                if self._is_held():
                    break
                self.loop.step()

    def run_realtime(self, stop: Event) -> None:
        """Advance one tick every tick_seconds / speed real seconds."""
        interval = self.act.tick_seconds / self.speed if self.speed else 1.0
        while not stop.is_set():
            if stop.wait(interval):
                break
            self.advance(self.act.tick_seconds)

    def active_faults(self) -> list[dict[str, Any]]:
        """The world's active faults: id, type, environment."""
        with self.lock:
            return [
                {
                    "id": fault["id"],
                    "type": fault["type"],
                    "environment": fault["environment"],
                }
                for fault in self.world.list_faults()
            ]

    def clear_fault(self, fault_id: str) -> None:
        """Clear the fault and append the demo timeline event (d8-pins 4)."""
        from fleetsre.control.incidents import IncidentState
        from fleetsre.control.postmortem import TimelineEvent

        with self.lock:
            known = {
                fault["id"]: fault
                for fault in self.world.list_faults()
            }
            if fault_id not in known:
                self.world.clear(fault_id)
                return
            environment = known[fault_id]["environment"]
            self.world.clear(fault_id)
            closed = frozenset({
                IncidentState.RESOLVED, IncidentState.ESCALATED,
            })
            for record in self.manager.incidents():
                deployment = record.incident.deployment
                env = deployment.split("/", 1)[-1]
                if record.state in closed or env != environment:
                    continue
                record.timeline.append(TimelineEvent(
                    at=self.clock.now(), kind="demo",
                    detail={
                        "action": "mark_rotated", "fault": fault_id,
                    },
                ))
","path":"fleetsre/demo/runtime.py"}

{"content":""""Pure view functions for the demo web app (d8-pins 8, 12-15)."""

from datetime import timedelta
from typing import Any

READ_TOOLS = frozenset({
    "query_logs",
    "get_resource",
    "list_connector_logs",
    "list_job_logs",
    "test_integration_instance",
    "compare_siblings",
    "tripwire_history",
    "get_contract",
})


def _transcript_records(rt: Any, record: Any) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for transcript_id in record.transcript_ids:
        out.extend(rt.store.transcript(transcript_id))
    return out


def _elide_encrypted(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {
            key: (
                f"<encrypted: {len(value)} chars>"
                if key == "encrypted_content"
                and isinstance(value, str)
                else _elide_encrypted(value)
            )
            for key, value in obj.items()
        }
    if isinstance(obj, list):
        return [_elide_encrypted(item) for item in obj]
    return obj


def _load_session(rt: Any, incident_id: str) -> Any | None:
    try:
        return rt.store.load(incident_id)
    except KeyError:
        return None


def _hypotheses_view(session: Any) -> list[dict[str, Any]]:
    if session is None:
        return []
    return [
        {
            "id": hypothesis.id,
            "statement": hypothesis.statement,
            "wouldConfirm": hypothesis.wouldConfirm,
            "alternative": hypothesis.alternative,
        }
        for hypothesis in session.hypotheses.values()
    ]


def _evidence_view(rt: Any, session: Any) -> list[dict[str, Any]]:
    if session is None:
        return []
    from fleetsre.ports import MemoryLogQuery

    log_query = MemoryLogQuery(rt.sink)
    items: list[dict[str, Any]] = []
    for recorded in session.evidence.values():
        if recorded.insertId is not None:
            entry = log_query.get(recorded.insertId)
            if entry is None:
                source: dict[str, Any] = {
                    "kind": "log", "insertId": recorded.insertId,
                }
            else:
                source = {
                    "kind": "log",
                    "insertId": recorded.insertId,
                    "timestamp": entry.timestamp.isoformat(),
                    "severity": entry.severity,
                    "event": entry.jsonPayload.get("event", ""),
                    "message": entry.jsonPayload.get("message", ""),
                    "deployment": recorded.deployment or "",
                }
        else:
            call = session.calls.get(recorded.callId or "")
            source = {
                "kind": "toolResult",
                "callId": recorded.callId,
                "tool": call.tool if call is not None else "",
                "field": recorded.field,
                "value": recorded.value,
            }
        items.append({
            "id": recorded.id,
            "hypothesis": recorded.hypothesis,
            "stance": recorded.stance,
            "why": recorded.why,
            "recordedAtTurn": recorded.recordedAtTurn,
            "source": source,
        })
    return items


def _proposal_view(proposal: Any) -> dict[str, Any]:
    method = proposal.method
    if method.endswith(".restart"):
        return {
            "hash": proposal.hash,
            "seq": proposal.seq,
            "method": method,
            "resource": proposal.resource,
            "update_mask": list(proposal.update_mask),
            "diff": [],
            "steps": "enabled: false \u2192 true",
        }
    if method.endswith(".runOnDemand"):
        return {
            "hash": proposal.hash,
            "seq": proposal.seq,
            "method": method,
            "resource": proposal.resource,
            "update_mask": list(proposal.update_mask),
            "diff": [],
            "steps": "run once",
        }
    before_resource: dict[str, Any] = getattr(
        proposal, "resource_before", {}
    ) or {}
    patch: dict[str, Any] = proposal.patch or {}
    mask: list[str] = list(proposal.update_mask or [])
    diff: list[dict[str, Any]] = []
    if "parameters" in mask:
        proposed = patch.get("parameters", [])
        current = {
            param.get("displayName"): param
            for param in before_resource.get("parameters", [])
        }
        for param in proposed:
            display = param.get("displayName", "")
            have = current.get(display, {})
            before_value = str(have.get("value", ""))
            after_value = str(param.get("value", ""))
            if have.get("type") == "PASSWORD":
                before_value = "********"
                after_value = "********"
            diff.append({
                "field": f"parameters[{display}]",
                "before": before_value,
                "after": after_value,
            })
    for field in mask:
        if field == "parameters":
            continue
        diff.append({
            "field": field,
            "before": before_resource.get(field, ""),
            "after": patch.get(field, ""),
        })
    return {
        "hash": proposal.hash,
        "seq": proposal.seq,
        "method": method,
        "resource": proposal.resource,
        "update_mask": mask,
        "diff": diff,
        "steps": None,
    }


def _verification_view(rt: Any, record: Any) -> dict[str, Any] | None:
    started_index: int | None = None
    tripwire = ""
    seconds = 0
    for index, event in enumerate(record.timeline):
        if event.kind == "verification_started":
            started_index = index
            tripwire = str(event.detail.get("tripwire", ""))
            seconds = int(event.detail.get("seconds", 0))
    if started_index is None:
        return None
    started_event = record.timeline[started_index]
    started_at = started_event.at
    outcome = "pending"
    for event in record.timeline[started_index + 1:]:
        if event.kind == "verified":
            outcome = "verified"
        elif event.kind == "verification_failed":
            outcome = "failed"
        elif event.kind == "verification_started":
            outcome = "pending"
    deployment = record.incident.deployment
    status = rt.evaluator.status().get(deployment, {})
    return {
        "tripwire": tripwire,
        "seconds": seconds,
        "started_at": started_at.isoformat(),
        "deadline": (started_at + timedelta(seconds=seconds)).isoformat(),
        "current": status.get(tripwire, "unknown"),
        "outcome": outcome,
    }


def _turns_view(
    records: list[dict[str, Any]], session: Any
) -> list[dict[str, Any]]:
    resumes = sorted(session.resumed_at_turns) if session is not None else []
    cards: list[dict[str, Any]] = []
    for stored in records:
        turn = stored["turn"]
        segment = 1 + sum(1 for point in resumes if point < turn)
        tool = stored.get("tool")
        args = stored.get("args") or {}
        if tool is None:
            think = ""
            act = None
            observe = None
        else:
            think = args.get("rationale", "") if isinstance(args, dict) else ""
            act = {
                "tool": tool,
                "args": {
                    key: value for key, value in args.items()
                    if key != "rationale"
                },
            }
            output = stored.get("output")
            if isinstance(output, dict) and "result" in output:
                observe = output["result"]
            else:
                observe = output
        cards.append({
            "n": turn,
            "segment": segment,
            "think": think,
            "act": act,
            "observe": observe,
            "verdict": stored.get("verdict"),
            "usage": stored.get("usage"),
        })
    return cards


def _header_view(records: list[dict[str, Any]]) -> dict[str, Any]:
    tokens = {
        key: sum(
            (record.get("usage") or {}).get(key, 0) for record in records
        )
        for key in (
            "input_tokens", "output_tokens", "reasoning_tokens",
            "cached_tokens",
        )
    }
    refusals: dict[str, int] = {}
    for record in records:
        if record.get("verdict") == "refused":
            for problem in record.get("problems") or []:
                rule = str(problem).split(":", 1)[0]
                refusals[rule] = refusals.get(rule, 0) + 1
    return {
        "turns": len(records),
        "model_calls": len(records),
        "read_calls": sum(
            1 for record in records
            if record.get("verdict") == "accepted"
            and record.get("tool") in READ_TOOLS
        ),
        "tokens": tokens,
        "cost_usd": sum(record.get("cost_usd", 0.0) for record in records),
        "refusals": refusals,
    }


def _handoff_view(
    rt: Any, record: Any, session: Any, records: list[dict[str, Any]]
) -> dict[str, Any] | None:
    state = record.state.value if hasattr(record.state, "value") else str(
        record.state
    )
    if state != "NEEDS_INPUT":
        return None
    last_refused = next(
        (item for item in reversed(records)
         if item.get("verdict") == "refused"),
        None,
    )
    if last_refused is None:
        last_refusal = None
    else:
        last_refusal = {
            "n": last_refused["turn"],
            "tool": last_refused.get("tool"),
            "problems": list(last_refused.get("problems") or []),
        }
    reason = record.reason
    escalation_summary = None
    if reason == "escalated" and record.diagnosis:
        escalation_summary = (record.diagnosis.get("action") or {}).get(
            "escalationSummary"
        )
    paused_at = record.paused_at
    if paused_at is None:
        since_pause = 0
        paused_text = None
    else:
        since_pause = sum(
            1 for at in rt.call_times if at > paused_at
        )
        paused_text = paused_at.isoformat()
    return {
        "reason": reason,
        "hypotheses": _hypotheses_view(session),
        "evidence": _evidence_view(rt, session),
        "last_refusal": last_refusal,
        "escalation_summary": escalation_summary,
        "paused_at": paused_text,
        "model_calls_since_pause": since_pause,
    }


def fleet_view(rt: Any) -> dict[str, Any]:
    """Grid data: act, now, held, services x deployments (d8-pins 12)."""
    act_name = getattr(rt, "act_name", "") or ""
    status = rt.evaluator.status()
    ordered: list[Any] = list(rt.evaluator.deployments)
    services: list[dict[str, Any]] = []
    by_service: dict[str, list[dict[str, Any]]] = {}
    order: list[str] = []
    for deployment in ordered:
        contract = rt.registry.contract(deployment.service)
        dep_status = status.get(deployment.id, {})
        components: list[dict[str, Any]] = []
        for component in contract.components:
            tripwires = [
                {
                    "id": tripwire.id,
                    "status": dep_status.get(tripwire.id, "ok"),
                }
                for tripwire in contract.tripwires
                if tripwire.component == component.id
            ]
            health = (
                "tripped"
                if any(item["status"] == "tripped" for item in tripwires)
                else "ok"
            )
            components.append({
                "id": component.id,
                "kind": component.kind,
                "health": health,
                "tripwires": tripwires,
            })
        dep_health = (
            "tripped"
            if any(item["health"] == "tripped" for item in components)
            else "ok"
        )
        candidates = [
            item for item in rt.manager.incidents()
            if item.incident.deployment == deployment.id
        ]
        if candidates:
            latest = max(
                candidates,
                key=lambda item: (item.incident.opened_at, item.id),
            )
            incident: dict[str, Any] | None = {
                "id": latest.id,
                "state": latest.state.value
                if hasattr(latest.state, "value") else str(latest.state),
            }
        else:
            incident = None
        view = {
            "id": deployment.id,
            "environment": deployment.environment,
            "health": dep_health,
            "incident": incident,
            "components": components,
        }
        if deployment.service not in by_service:
            by_service[deployment.service] = []
            order.append(deployment.service)
        by_service[deployment.service].append(view)
    for service in order:
        services.append({
            "service": service, "deployments": by_service[service],
        })
    return {
        "act": act_name,
        "now": rt.clock.now().isoformat(),
        "held": bool(rt.held),
        "services": services,
    }


def incident_view(rt: Any, incident_id: str) -> dict[str, Any]:
    """Incident data: hypotheses, evidence, proposal, turns, handoff (13-15)."""
    record = rt.manager.get(incident_id)
    session = _load_session(rt, incident_id)
    records = _transcript_records(rt, record)
    proposals = list(record.proposals or [])
    timeline = [
        event.model_dump(mode="json")
        if hasattr(event, "model_dump") else dict(event)
        for event in record.timeline
    ]
    postmortem = record.postmortem
    return {
        "id": record.id,
        "deployment": record.incident.deployment,
        "state": record.state.value
        if hasattr(record.state, "value") else str(record.state),
        "reason": record.reason,
        "tripwires": list(record.tripwires),
        "timeline": timeline,
        "postmortem": (
            postmortem.model_dump(mode="json")
            if postmortem is not None else None
        ),
        "hypotheses": _hypotheses_view(session),
        "evidence": _evidence_view(rt, session),
        "diagnosis": record.diagnosis,
        "proposal": _proposal_view(proposals[-1]) if proposals else None,
        "verification": _verification_view(rt, record),
        "turns": _turns_view(records, session),
        "header": _header_view(records),
        "handoff": _handoff_view(rt, record, session, records),
    }


def turn_input(rt: Any, incident_id: str, turn: int) -> list[dict[str, Any]]:
    """Exact model input of turn n, encrypted_content elided (d8-pins 14)."""
    record = rt.manager.get(incident_id)
    records = _transcript_records(rt, record)
    seen = {item["turn"] for item in records}
    if turn not in seen:
        raise ValueError(f"unknown turn: {turn}")
    transport = rt.transport
    if transport is not None:
        requests = transport.requests
    else:
        requests = rt._counting.requests
    if turn < 1 or turn > len(requests):
        raise ValueError(f"unknown turn: {turn}")
    return _elide_encrypted(requests[turn - 1]["input"])
