{"content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Fleet SRE demo — {{ fleet.act }}</title>
<style>
body { font-family: system-ui, -apple-system, Segoe UI, sans-serif; margin: 0 auto; max-width: 72rem; padding: 1rem 1.5rem 4rem; color: #1a1a1a; background: #fff; }
header { border-bottom: 2px solid #1a1a1a; padding-bottom: 0.75rem; margin-bottom: 1rem; }
header p { margin: 0.2rem 0; }
.notice { font-weight: 700; }
table.grid { border-collapse: collapse; width: 100%; margin: 0.5rem 0 1.5rem; }
table.grid th, table.grid td { border: 1px solid #999; padding: 0.4rem 0.6rem; text-align: left; vertical-align: top; }
.health-ok { background: #e6f4ea; }
.health-tripped { background: #fce8e6; }
.tw { font-size: 0.85em; color: #333; }
#stale { display: none; font-weight: 700; }
.actbar button { margin-right: 0.5rem; }
a { color: #0b57d0; }
</style>
</head>
<body>
<header>
<p>Act: {{ fleet.act }} &mdash; {{ demo.title }}</p>
<p>Sim time: {{ fleet.now }}</p>
<p>Held: {{ "yes" if fleet.held else "no" }}</p>
{% if fleet.held %}<p class="notice">clock held: awaiting approval</p>{% endif %}
<p>Model calls: {{ demo.model_calls }}{% if demo.last_model_call_at %} (last: {{ demo.last_model_call_at }}){% endif %}</p>
<p>Active faults:{% if demo.active_faults %} {% for f in demo.active_faults %}{{ f.id }} {{ f.type }} {{ f.environment }}{% if not loop.last %}; {% endif %}{% endfor %}{% else %} none{% endif %}</p>
{% if demo.exhausted %}<p class="notice">script ended: switch act to restart</p>{% endif %}
<p id="stale">updated: reload</p>
</header>
<h1>Fleet grid</h1>
{% for service in fleet.services %}
<h2>{{ service.service }}</h2>
<table class="grid">
<thead><tr><th>Deployment</th>{% for comp in service.deployments[0].components %}<th>{{ comp.id }}</th>{% endfor %}<th>Incident</th></tr></thead>
<tbody>
{% for dep in service.deployments %}
<tr>
<td>{{ dep.id }}</td>
{% for comp in dep.components %}
<td class="health-{{ comp.health }}">{{ comp.health }}{% for tw in comp.tripwires %}<div class="tw">{{ tw.id }}: {{ tw.status }}</div>{% endfor %}</td>
{% endfor %}
<td>{% if dep.incident %}<a href="/incidents/{{ dep.incident.id }}">{{ dep.incident.id }} ({{ dep.incident.state }})</a>{% else %}&mdash;{% endif %}</td>
</tr>
{% endfor %}
</tbody>
</table>
{% endfor %}
{% if admin %}
<div class="actbar">
<h2>Switch act</h2>
{% for name in demo.acts %}
<button data-act="{{ name }}">{{ name }}</button>
{% endfor %}
</div>
<script>
document.querySelectorAll("[data-act]").forEach(function (el) {
  el.addEventListener("click", function () {
    fetch("/api/demo/act", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({act: el.dataset.act})}).then(function () { window.location.reload(); });
  });
});
</script>
{% endif %}
<script>
(function () {
  var known = null;
  function poll() {
    fetch("/api/version").then(function (r) { return r.json(); }).then(function (data) {
      if (known === null) { known = data.version; return; }
      if (data.version !== known) {
        if (document.querySelector("details[open]")) {
          document.getElementById("stale").style.display = "block";
          known = data.version;
        } else { window.location.reload(); }
      }
    }).catch(function () {});
  }
  setInterval(poll, 2000);
})();
</script>
</body>
</html>
